package pk.edu.dsu.scd.lab03;import java.util.*;public final class LinkedStack<T> implements Stack<T>{private Node<T> top;private int n;private static final class Node<T>{T v;Node<T> next;Node(T v,Node<T> n){this.v=v;next=n;}}public void push(T x){top=new Node<>(x,top);n++;}public T pop(){if(isEmpty())throw new NoSuchElementException();T x=top.v;top=top.next;n--;return x;}public T peek(){if(isEmpty())throw new NoSuchElementException();return top.v;}public boolean isEmpty(){return n==0;}public int size(){return n;}}